<script setup lang="ts">
import { NModal, NButton } from 'naive-ui'; import { useI18n } from 'vue-i18n'; defineProps<{ show: boolean; title: string; impacts: string[]; busy?: boolean }>(); defineEmits<{ 'update:show': [value: boolean]; confirm: []; cancel: [] }>(); const { t } = useI18n()
</script><template><NModal :show="show" preset="card" :title="title" style="width: min(560px, 92vw)" :mask-closable="!busy" :closable="!busy" @update:show="value => { $emit('update:show', value); if (!value) $emit('cancel') }"><p>{{ t('common.impact') }}</p><ul><li v-for="impact in impacts" :key="impact">{{ impact }}</li></ul><div class="actions"><NButton :disabled="busy" @click="$emit('update:show', false); $emit('cancel')">{{ t('common.cancel') }}</NButton><NButton type="primary" :loading="busy" @click="$emit('confirm')">{{ t('common.confirm') }}</NButton></div></NModal></template>
